-- Foreign Employment Act, 2064 (2007), extracted from supplied text.
CREATE TABLE IF NOT EXISTS legal_documents (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  "originalTitle" TEXT,
  "documentType" TEXT NOT NULL CHECK ("documentType" IN ('constitution','act','regulation','schedule_only')),
  "yearBs" NUMERIC NOT NULL,
  "yearAd" NUMERIC NOT NULL,
  "totalPages" INTEGER NOT NULL CHECK ("totalPages" >= 0),
  nodes JSONB NOT NULL
);

INSERT INTO legal_documents (id,title,"originalTitle","documentType","yearBs","yearAd","totalPages",nodes) VALUES ($CODEx50c2f11be9af$doc_foreign_employment_act_2064_2007$CODEx50c2f11be9af$,$CODExfa784a96b59c$Foreign Employment Act, 2064 (2007)$CODExfa784a96b59c$,NULL,$CODEx76f3b5a7170a$act$CODEx76f3b5a7170a$,2064,2007,41,$CODEx0c941c7c1aa3$[{"tier": 1, "nodeType": "preamble", "identifier": "Preamble", "title": "Introductory matter", "content": "Foreign Employment Act, 2064 (2007)\nDate of Authentication and Publication\n2064-05-19 (September 5, 2007)\nAct number 18 of the year 2064 (2007)\nAn Act Made to Amend and Consolidate Laws Relating to Foreign Employment\nPreamble: Whereas, it is expedient to amend and consolidate laws relating to foreign\nemployment in order to make foreign employment business safe, managed and decent\nand protect the rights and interests of the workers who go for foreign employment and\nthe foreign employment entrepreneurs, while promoting that business;\nNow, therefore, be it enacted by the Legislature-Parliament.", "children": []}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-1", "title": null, "content": "Preliminary", "children": [{"tier": 2, "nodeType": "rule", "identifier": "Rule 1", "title": "Short title, extension and commencement", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "This Act may be called\n\"Foreign Employment Act, 2064 (2007)\".", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "It shall extend throughout Nepal and also apply to one who stays\noutside Nepal and commits any act contrary to this Act.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "This Act shall into force immediately.", "children": []}]}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 2", "title": "Definitions", "content": "Unless the subject or context otherwise requires in this Act,-", "children": [{"tier": 3, "nodeType": "clause", "identifier": "(a)", "title": null, "content": "\"Foreign employment\" means employment which a worker gets abroad.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(b)", "title": null, "content": "\"Worker\" means a citizen of Nepal who gets in foreign employment.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(c)", "title": null, "content": "\"Foreign employment business\" means a business carried on to provide\nemployment to citizen of Nepal in abroad.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(d)", "title": null, "content": "\"Department\" means the Department of Foreign Employment.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(e)", "title": null, "content": "\"Institution\" means an institution established under the prevailing\nCompanies Act to carry on the foreign employment business.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(f)", "title": null, "content": "\"License\" means a license granted under Section 11 to carry on the\nforeign employment business.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(g)", "title": null, "content": "\"Licensee\" means an institution having obtained license pursuant to\nSection 11.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(h)", "title": null, "content": "\"Service charge\" means a sum of money charged by a foreign\nemployment entrepreneur for sending a worker abroad.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(i)", "title": null, "content": "\"Executive Director\" means the Executive Director as referred to in\nSection 41.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(j)", "title": null, "content": "\"Employer institution\" means an abroad based institution providing a\nworker with employment in abroad.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(k)", "title": null, "content": "\"Board\" means the Foreign Employment Promotion Board constituted\npursuant to Section 38.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(l)", "title": null, "content": "\"Labor Attaché\" means the labor attaché appointed pursuant to Section\n68, and this term also includes an officer employee, in an abroad-based\ndiplomatic mission, entrusted with the responsibility for the promotion\nof the interests of Nepalese workers.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(m)", "title": null, "content": "\"Prescribed\" or \"As prescribed\" means prescribed or as prescribed in the\nRules framed under this Act.", "children": []}]}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-2", "title": null, "content": "Provisions Relating Foreign Employment", "children": [{"tier": 2, "nodeType": "rule", "identifier": "Rule 3", "title": "Specification of countries for carrying on foreign employment business", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The Government of Nepal shall, by a notification in the Nepal Gazette, specify\ncountries for carrying on the foreign employment business.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "Out of the countries specified pursuant to Sub-section (1), the\nGovernment of Nepal may prohibit the carrying on of the foreign employment\nbusiness in any country and suspend such business for a certain period.", "children": []}]}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 4", "title": "Power to make bilateral agreement", "content": "The Government of Nepal may make a\nbilateral labor agreement with a foreign country where the citizens of Nepal\nhave gone or may go for foreign employment.", "children": []}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 5", "title": "Selection of institution", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "If any foreign country or employer institution\nmakes a request to the Government of Nepal to select and send workers, the\nGovernment of Nepal may select any licensee institution through open\ncompetition and send workers through such institution.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The Department shall demand additional cash deposit or bank\nguarantee from the institution selected pursuant to Sub-section (1).", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The grounds and procedures for the selection of institution pursuant\nto Sub-section (1) shall be as prescribed.", "children": []}]}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 6", "title": "Power to send workers by making a treaty or an agreement", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "Notwithstanding anything contained elsewhere in this Act, the Government of\nNepal may make a treaty or an agreement with the government of a country\nhaving diplomatic relations with Nepal and send workers to such country\nthrough any office, institution of the Government of Nepal or any institution\nfully owned by the Government of Nepal.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "There shall be a steering committee as follows for formulating\npolicies and making other arrangements required to make systematic,\ncompetitive and transparent the procedures to be followed while sending\nworkers by the Government of Nepal pursuant to Sub-section (1):-\n(a)     Minister or Minister of State for Labor and -Chairperson\nTransport Management\n(b)     Secretary, Ministry of Labor and Transport -Member\nManagement\n(c)     Representative   (Joint    Secretary   level), -Member\nMinistry of Finance\n(d)     Representative   (Joint    Secretary   level), -Member\nMinistry of Industries, Commerce and\nSupplies\n(e)     Representative   (Joint    Secretary   level), -Member\nMinistry of Home Affairs\n(f)     Representative   (Joint    Secretary   level), -Member\nMinistry of Foreign Affairs\n(g)     Executive Director                            -Member\n(h)     Woman representative, National Women -Member\nCommission\n(i)     One representative from each recognized -Member\ntrade union federation\n(j)     One representative of foreign entrepreneurs' -Member\nassociations\n(k)     Director General, Department                  -Member\nSecretary", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The steering committee referred to in Sub-section (2) may, as\nrequired, invite any native or foreign expert in the field of foreign employment\nas an observer to its meeting.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "The steering committee referred to in Sub-section (2) shall\nmanage its procedures on its own.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "The selection of persons required as workers to be sent pursuant\nto this Section shall be made from amongst the persons who have fulfilled the\nprescribed standards and procedures on the basis of impartiality and\ntransparency.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "It shall be the obligation of the Government of Nepal to solve a\nproblem, if any, arising for any worker going on foreign employment pursuant\nto this Section.", "children": []}]}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 7", "title": "Prohibition on sending a minor for employment", "content": "Any minor who has not\ncompleted eighteen years of age shall not be sent for foreign employment.", "children": []}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 8", "title": "Prohibition on gender discrimination", "content": "No gender discrimination shall be\nmade while sending workers for foreign employment pursuant to this Act.\nProvided that where an employer institution makes a demand for either male or\nfemale workers, nothing shall prevent the sending of workers for foreign\nemployment according to that demand.", "children": []}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 9", "title": "To provide special facility and reservation", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The Government of Nepal\nmay provide special facility to the women, Dalit, indigenous nationalities,\noppressed, victims of natural calamities and people of remote areas who go for\nforeign employment.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "In sending workers for foreign employment, any institution shall\nprovide reservation to the women, Dalit, indigenous nationalities, oppressed\nclass, backward area and class and people of remote areas in the number as\nprescribed by the Government of Nepal.", "children": []}]}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-3", "title": null, "content": "Provisions Relating to License", "children": [{"tier": 2, "nodeType": "rule", "identifier": "Rule 10", "title": "Prohibition on carrying on foreign employment business without license", "content": "No one shall carry on the foreign employment business without         obtaining    a\nlicense pursuant to this Act.", "children": []}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 11", "title": "Provisions relating to license", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "An institution intending to carry on the\nforeign employment business shall make an application to the Department for\nthe license setting out the details as prescribed.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "If, upon making necessary inquiry into an application made\npursuant to Sub-section (1), it appears appropriate to grant the license to such\ninstitution to carry on the foreign employment business, the Department shall\ngrant the license, upon collecting the license fees as prescribed and a sum of\nthree million rupees in cash or seven hundred thousand rupees in cash and a\nbank guarantee of the remaining two million three hundred thousand rupees as\na deposit.\nExplanation: For the purposes of this Act, the term \"bank guarantee\" means a\nbank guarantee so issued by the bank specified by the Department that cash\npayment is made by the bank as and when so demanded by the Department.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The   institutions   having   obtained   license   prior   to    the\ncommencement of this Act shall make deposit as referred to in Sub-section (2)\nwithin one year from the date of commencement of this Act.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "If, after the license has been obtained by furnishing the deposit\npursuant to Sub-section (2), the deposit appears to be insufficient in proportion\nto the transactions of the licensee, the Department shall issue an order to\nfurnish additional deposit, as required.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "The Department may accept a bank guarantee for the additional\ndeposit to be furnished pursuant to Sub-section (4).", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "If, on inquiring into the application pursuant to Sub-section (2), it\nappears that the license cannot be granted, the Department shall give\ninformation thereof, accompanied by the reason, to the applicant within seven\ndays of the decision not to grant the license.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(7)", "title": null, "content": "The applicant who is not satisfied with the decision made by the\nDepartment pursuant to Sub-section (6) may make an appeal to the Government\nof Nepal within thirty-five days after the date of receipt of such information\nand a decision made by the Government in relation to the appeal shall be final.", "children": []}]}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 12", "title": "Period and renewal of license", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "Except where the license is canceled\npursuant to Section 13, the license shall remain valid for up to one financial\nyear. The period of such license shall expire at the end of that financial year\ndespite the fact that the license has been issued on any date whatsoever.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "A licensee who intends to get the license renewed may get the\nlicense renewed by furnishing the details and fees as prescribed within the\nprescribed time in each financial year.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "Notwithstanding anything contained in Sub-section (1) or (2), any\nlicensee may get the license renewed for three financial years by paying the\nrenewal fees for three financial years at the same time.", "children": []}]}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 13", "title": "Revocation of license", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "If a licensee fails to get renewed within the period\nreferred to in Section 12, such license shall be revoked.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "If a licensee does any of the following acts, the Department may\nrevoke the license obtained by the licensee:-\n(a)     Obtaining the license by submitting fake documents or\ndetails,\n(b)     Failing to furnish cash deposit within the period referred\nto in Sub-section (3) of Section 11,\n(c)     Failing to furnish additional deposit pursuant to the\norder issued under Sub-section (4) of Section 11,\n(d)     Failing to reimburse the deposit pursuant to Sub-section", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "of Section 35,\n(e)     Doing any act contrary to this Act or the rules framed\nunder this Act.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "Prior to revoking the license pursuant to Sub-section (2), the\nDepartment shall provide the concerned licensee with an opportunity for\ndefense.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "The licensee, who is not satisfied with the decision made to\nrevoke the license pursuant to this Section, may make an appeal       to        the\nGovernment of Nepal within thirty-five days of the date          of   receipt    of\ninformation of the decision to revoke the license the decision made by the\nGovernment of Nepal in relation to the appeal shall be final.", "children": []}]}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 14", "title": "Prohibition on transfer of or change in ownership or liability", "content": "Notwithstanding anything contained in the prevailing laws, no licensee shall,\nwithout approval of the Department, transfer or change the ownership or\nliability of the institution.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-4", "title": null, "content": "Provisions Relating to Prior Approval and Selection of Workers", "children": [{"tier": 2, "nodeType": "rule", "identifier": "Rule 15", "title": "Prior approval to be obtained", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "A licensee shall make an application\nsetting out the following details, based on the agreement or understanding made\nwith an employer institution, to the Department for prior approval to send\nworkers for foreign employment:-\n(a)      Name and address of the employer institution and      country\nwhere workers are to be sent,\n(b)      Type of foreign employment,\n(c)      Type and number of workers,\n(d)      Salary, facilities and leave to be obtained by workers,\n(e)      working days and time to be done by the works .\n(f)      Original copy of the demand letter and authority certified by the\nauthentic body or diplomatic mission or labor attaché or chamber\nof commerce or notary public of the country where workers go for\nforeign employment,\n(g)      A copy of the contract to be made between the employer\ninstitution and workers,\n(h)      A copy of the contract to be made between the licensee and\nworkers,\n(i)      Other matters as prescribed.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "If, on inquiring into the application made pursuant to Sub-section", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": ", the demand of the licensee appears appropriate, the Department shall, no\nlater than four days after the date of application, give prior approval to start\naction to send Nepalese workers for foreign employment.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "Notwithstanding anything contained in Sub-section (2), the\nDepartment shall not give prior approval to select workers under any of the\nfollowing conditions:-\n(a)      The terms and conditions of service and facilities are not\nsatisfactory in proportion to the qualification of the worker\ndemanded by the employer institution,\n(b)      The proposed foreign employment seems to be of such          nature\nas to have adverse effect on the dignity, prestige or health of\nworkers,\n(c)      It appears inappropriate from security perspective,\n(d)      There exist other conditions as prescribed.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "If a decision is made not to give prior approval pursuant to Sub-\nsection (3), information thereof, accompanied by the reason for the same, shall\nbe given to the applicant.", "children": []}]}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 16", "title": "Publication of advertisement", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "On receipt of approval pursuant to Section\n15, the licensee shall publish an advertisement in a daily newspaper of national\ncirculation to be published in the Nepali language, setting out the details as\nprescribed and giving the time-limit of at least seven days, for the selection of\nthe workers.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The concerned licensee shall post a notice of advertisement\npublished pursuant to Sub-section (1) on the notice-board of its office and\nsubmit a copy of that notice to the Department on the same day.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "After the publication of advertisement pursuant to Sub-section (1),\na person who intends to go for foreign employment shall make an application,\naccompanied by the prescribed details, to the licensee.", "children": []}]}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 17", "title": "List to be prepared after selecting workers", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "Upon receipt of an\napplication pursuant to Sub-section (3) of Section 15, the licensee shall select\nworkers on the grounds of qualification and experience of applicants and other\nmatters as prescribed, according to the nature of work demanded . The licensee\nshall prepare a list of selected persons, post such list on the notice board of the\noffice of the licensee and submit a copy thereof to the Department.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "If a complaint is made by any person or the Department\nitself receives an information in any manner that any irregularity has been made\nin the preparation of workers list pursuant to Sub-section (1), the Department\nmay immediately make necessary inquiry thereinto; and if, in making such\ninquiry, it appears that any irregularity has been made as mentioned in the\ncomplaint or petition, the Department shall give order to immediately stop all\nacts relating to the selection of workers.", "children": []}]}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 18", "title": "Approval required to take passports to the abroad", "content": "If a licensee has to take\npassports of those persons who have been selected for foreign employment\npursuant to Section 17 outside Nepal for visas, approval of the Department has\nto be obtained.", "children": []}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 19", "title": "Provisions relating to labor permission sticker", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "After receiving visas of\nworkers selected pursuant to Section 17 and before sending such workers for\nforeign employment, the licensee shall make a submission, accompanied by the\nfollowing details, to the Department for labor permission sticker:-\n(a)    In the event that skill-oriented training is required for any work, a\ncertificate of such training and a certificate of orientation training,\n(b)    Health certificate,\n(c)    Insurance certificate,\n(d)    Contract made between the licensee and the worker,\n(e)      Contract made between the employer institution and the\nworker,\n(f)      A receipt or bank voucher of amount paid by the worker        to the\nlicensee,\n(g)      Other matters as prescribed.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "If, in examining the details submitted pursuant to Sub-section (1),\nthe details are found to be in conformity with the details submitted pursuant to\nSection 15, the Department shall affix the labor permission sticker on the\npassport of such worker.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "If the information provided pursuant to Sub-section (1) is found to\nbe inconsistent with the details submitted pursuant to Section 15, the\nDepartment may prevent the licensee from sending workers for foreign\nemployment, and the information, accompanied by the reason for such\nprevention, shall be given to the licensee.", "children": []}]}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 20", "title": "To send for foreign employment", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "upon giving information pursuant to\nSection 19, the licensee shall send the concerned worker for foreign\nemployment within the specified period to enter into the concerned country, if\nany, and within three months if such period is not specified.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "In the event of failure to send a worker for foreign employment\nwithin the time-limit as referred to in Sub-section (1), the concerned licensee\nshall return the amount received from the concerned worker, as well as an\ninterest on that amount at the rate of twenty percent per annum, to the\nconcerned worker within thirty days.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "If, after having obtained a visa, any worker refuses or is not able\nto go for foreign employment, the licensee shall, in returning the amount to the\nworker, return the remaining amount to be set after deducting the visa fee only.\nProvided that if the worker refuses to go by the reason of any terms\ndifferent than those advertised by obtaining prior approval, the visa fee shall\nnot be deducted.", "children": []}]}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 21", "title": "To go for foreign employment on personal basis", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "If any person intends to\ngo abroad for foreign employment on personal basis, such person shall make an\napplication, setting out the following matters, to the Department for approval:-\n(a)      Country intended to be visited for employment,\n(b)      Nature of work to be done abroad,\n(c)      Letter of approval granted by the employer institution,\n(d)      Agreement clearly mentioning the terms and facilities of\nemployment,\n(e)      Certificate showing that orientation training has been       taken,\n(f)      Health certificate.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "If, in making necessary inquiry on receipt of the application\nreferred to in Sub-section (1), the request of the applicant appears to be\nappropriate, the Department shall give permission to the applicant to go abroad\nfor employment, and in so giving permission, the Department shall require the\napplicant to submit an insurance certificate.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "Notwithstanding anything contained in this Section, no licensee\nshall send workers on personal basis.", "children": []}]}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 22", "title": "Native airport to be used", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "While   sending    workers     for   foreign\nemployment, the licensee shall so send them that they use native airport.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "Where workers have to be sent by using any foreign airport\nshowing reasons such as non-availability of air tickets for sending workers by\nusing the native airport pursuant to Sub-section (1), approval of the Department\nhas to be obtained.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "While going outside Nepal to use the foreign airport by obtaining\napproval of the Department pursuant to Sub-section (2), registration, as\nprescribed, has to be made with the immigration office of the departure point.", "children": []}]}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 23", "title": "Power to specify minimum remuneration", "content": "The Government of Nepal may, by\na notification in the Nepal Gazette, specify the minimum remuneration to be\nreceived by workers who go for foreign employment.", "children": []}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 24", "title": "Service charge and promotional costs", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The Government of Nepal may,\nin relation to any specific country or company, specify the upper limit of\namount, including the service fee and promotional costs that the institution can\ncollect from each worker.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "After the licensee has given information that visa has been\nreceived from the concerned country for a worker selected for foreign\nemployment, the worker shall deposit the amount as referred to in the contract\nwith the office or in the bank account of the licensee.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "In the event that amount is deposited with the office of the\nlicensee pursuant to Sub-section (2), a receipt thereof shall be given to the\nworker.\nExplanation: For the purposes of this Section, \"promotional costs\" means the\nvisa fee chargeable for sending a worker for employment and miscellaneous\nexpenses made within and outside the country, in the course of receiving the\nquota of workers.", "children": []}]}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 25", "title": "Foreign employment contract to be made", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "Prior to the departure of a\nworker for foreign employment, a contract shall be made between the employer\ninstitution or its agent and the worker and the licensee and the worker on the\nterms and conditions of employment, terms and conditions to be observed by\nboth parties and remuneration to be received by the worker, after getting the\nworker to clearly understand such terms and conditions and provisions of\nremuneration.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The licensee shall translate the contract referred to in Sub-section", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "into the Nepali language and submit two copies thereof to the Department\nand the Department shall certify copies of such contract, retain one copy\nthereof in the Department and provide the other copy to the worker.", "children": []}]}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 26", "title": "Insurance to be procured", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The licensee shall, prior to sending a worker\nfor foreign employment, procure insurance of at least five hundred thousand\nrupees with validity for the term of contract so that such worker can claim\ndamages for death or mutilation, if such worker who has gone for foreign\nemployment pursuant to this Act dies from any cause at any time or gets\nmutilated.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "Even a person who goes for foreign employment personally\npursuant to Section 21 shall, prior to going for foreign employment, shall make\ninsurance equivalent to the amount set forth in Sub-section (1).", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "Other provisions relating to insurance shall be as prescribed.", "children": []}]}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-5", "title": null, "content": "Provisions Relating to Classification of Training and Workers", "children": [{"tier": 2, "nodeType": "rule", "identifier": "Rule 27", "title": "Training to be taken", "content": "Any worker who goes for foreign employment shall,\nprior to going for foreign employment, take orientation training, as prescribed,\nfrom the institution having obtained permission from the Department pursuant\nto Section 28.", "children": []}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 28", "title": "Provisions relating to institution running orientation training", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "An\ninstitution intending to provide orientation training to workers who go for\nforeign employment shall make an application to the Department for\npermission to run such orientation training.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The Department shall submit the application received pursuant to\nSub-section (1) to the Board.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "If, in making necessary inquiry into the application received\npursuant to Sub-section (2), the infrastructures, human resources as well as\nother means and resources of the institution providing the orientation training\nappear adequate, the Board shall write to the Department to provide license to\nthe applicant to run the orientation training to be given to workers who go for\nforeign employment.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "If so written to provide the license pursuant to Sub-section (3), the\nDepartment shall provide the applicant with the license to run the orientation\ntraining by collecting the deposit and license fees, as prescribed.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "If any institution which is running the training after having\nobtained permission at the time of commencement of this Act meets the criteria\nand terms as referred to in this Section, the Department shall make renewal.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "Provisions relating to the renewal of license provided to any\ninstitution to run the orientation training pursuant to this Section and the\nrenewal fees shall be as prescribed.", "children": []}]}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 29", "title": "Fixation of curriculum and standard of orientation training", "content": "The Board\nshall determine the curriculum and standard of the orientation training to be\nprovided by the institution running the orientation training which has obtained\nlicense pursuant to Section 28.", "children": []}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 30", "title": "Skill-oriented training to be taken", "content": "A worker going for foreign employment to\ndo any work requiring      any skill-oriented training shall obtain such training\nfrom an institution recognized by the Government of Nepal.\nExplanation: For the purposes of this Section, \"institution recognized      by the\nGovernment of Nepal\" means the Council for Technical            Education         and\nVocational Training and any other institution which has been established under\nthe prevailing law to provide similar training and affiliated with that Council.", "children": []}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 31", "title": "Classification of workers", "content": "The Government of Nepal may, by a notification in\nthe Nepal      Gazette, specify the provisions relating to the classification of\nworkers who go for foreign employment and the skill-oriented training to be\ntaken according to the classification.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-6", "title": null, "content": "Provisions Relating to Foreign Employment Welfare Fund", "children": [{"tier": 2, "nodeType": "rule", "identifier": "Rule 32", "title": "Establishment of foreign employment welfare fund", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "A foreign\nemployment welfare fund shall be established under the Board for the social\nsecurity and welfare of the workers who have gone for foreign employment and\nreturned from foreign employment and their families.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The following amounts shall be credited to the fund referred to in\nSub-section (1):-\n(a)      Amounts deposited as prescribed by the workers prior to going for\nforeign employment,\n(b)      Interest amount earned by mobilizing, as prescribed, the\ndeposits furnished pursuant to Sub-section (2) of Section    11,\n(c)      Amount received by way of license fees and license renewal fees,\n(d)      Fees for license to be provided to the institutions running training\npursuant to Section 28 and the license renewal fees,\n(e)      Amounts received by the fund from time to time from the\ninstitutions related with the foreign employment business,\n(f)      Grants and assistance received from any native or foreign persons\nor bodies.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "Prior to receiving assistance from any foreign person or body\npursuant to clause (f) of Sub-section (2), approval of the Government of Nepal\nshall be obtained.\nExplanation: For the purposes of this Act, the term \"family\" means the\nhusband or wife, son, daughter or mother, father and her father-in-law and\nmother-in-law, in the case of a female worker, whom the worker who has gone\nfor foreign employment and returned from foreign employment has to maintain\nand subsist on his or her own.", "children": []}]}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 33", "title": "Use and operation of foreign employment welfare fund", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The foreign\nemployment welfare fund shall be used for the following purposes:-\n(a)      Providing skill-oriented training to the workers going for foreign\nemployment,\n(b)      Repatriating workers to Nepal due to mutilation or   reason\nreferred to in Sub-section (1) of Section 75, providing\ncompensation to workers and providing financial assistance to the\nworkers who have so come back or their families,\n(c)      Launching employment-oriented programs for the workers who\nhave come back from foreign employment,\n(d)      Where a worker who has gone abroad for foreign       employment\ndies there and his or her dead body is not    attended   by   any\none, bringing the dead body to Nepal     and providing financial\nassistance to his or her family,\n(e)      Carrying out acts relating to foreign employment     promotion,\n(f)      Carrying out other acts as prescribed.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "Other provisions relating to the operation of the foreign\nemployment welfare fund shall be as prescribed.", "children": []}]}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-7", "title": null, "content": "Provisions Relating to Monitoring and Inquiry", "children": [{"tier": 2, "nodeType": "rule", "identifier": "Rule 34", "title": "Monitoring", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The Department shall monitor and inspect, from time to time,\nthe office of the licensee in relation to whether this Act or the rules framed\nunder this Act or direction given under this Act have been observed or not and\nfor this purpose, it may inspect the records and other relevant documents\nmaintained by the licensee.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "It shall be the duty of the licensee to provide such details and\nrecords as demanded at the time of making monitoring or inspection pursuant\nto Sub-section (1).", "children": []}]}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 35", "title": "Inquiry", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "In cases where a complaint is made by a worker that the employer\ninstitution has not fulfilled the contractual obligation or the licensee has not\ntaken necessary and appropriate action to get fulfilled the terms and conditions\nset forth in the contract, the Department may make, or cause to be made,\nnecessary inquiry thereinto.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "If, upon an inquiry made pursuant to Sub-section (1), it appears\nnecessary to bring the concerned worker back to Nepal, the Department shall\norder the licensee to provide such amount as is needed to bring the worker back\nto Nepal.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "In the event of failure to provide such amount in pursuance of the\norder issued by the Department pursuant to Sub-section (2), such worker shall\nbe brought back to Nepal by spending the deposit furnished by the licensee\npursuant to Section 11. Where the deposit is so spent, a notice shall be given to\nthe concerned licensee to reimburse the amount as soon as possible, and the\nlicensee shall reimburse that amount into the deposit no later than fifteen days\nof the receipt of such notice.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "If the expenses required to bring the worker back to Nepal cannot\nbe met from the deposit furnished pursuant to Section 11, the licensee shall pay\nsuch shortfall amount within the time-limit specified by the Department and in\nthe event of failure to make payment within such time-limit, the amount shall\nbe realized as if it were a governmental due.", "children": []}]}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 36", "title": "Complaint for compensation", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "If any employer institution does not provide employment in accordance\nwith the terms prescribed in the agreement, the worker or his or her\nagent may make a complaint, along with evidence, with the Department\nfor compensation.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "If, in making necessary inquiry into the complaint made pursuant\nto Sub-section (1), the contents seem to be reasonable, the Department may\ngive an order to the licensee to provide compensation for all expenses incurred\nin going for foreign employment.", "children": []}]}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 37", "title": "Power to give direction", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The Government of Nepal may, from time to\ntime, give necessary direction to any licensee in relation to foreign\nemployment.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "It shall be the duty of the concerned licensee to observe the\ndirection given pursuant to Sub-section (1).", "children": []}]}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-8", "title": null, "content": "Constitution, Functions, Duties and Powers of Board", "children": [{"tier": 2, "nodeType": "rule", "identifier": "Rule 38", "title": "Formation of Board", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "A Foreign Employment Promotion Board shall be\nconstituted as follows, also for the purpose of carrying out acts required to\npromote the foreign employment business and make this business safe,\nsystematic and decent and protect the rights and interests of workers going for\nforeign employment and the foreign employment entrepreneurs.\n(a)   Minister/Minister of State for Labor and -Chairperson\nTransport    Management        Ministry    of\nAgriculture and Cooperatives\n(b)   Minister of State/Assistant Minister for -Vice-\nLabor and Transport Management                  chairperson\n(c)   Member, National Planning (responsible for -Member\nthe concerned sector)\n(d)   Secretary, Ministry of Labor and Transport -Member\nManagement\n(e)   Secretary or Gazetted First Class level\nrepresentative designated by him or her, -Member\nMinistry of Home Affairs\n(f)   Secretary or Gazetted First Class level\nrepresentative designated by him or her, -Member\nMinistry of Foreign Affairs\n(g)   Secretary or Gazetted First Class level\nrepresentative designated by him or her, -Member\nMinistry of Finance\n(h)    Secretary or Gazetted First Class level\nrepresentative designated by him or her,\nMinistry of Law, Justice and Parliamentary\n-Member\nAffairs\n(i)    Secretary or Gazetted First Class level\nrepresentative designated by him or her,\nMinistry of Women, Children and Social\nWelfare                                            -Member\n(j)   Director General, Department                       -Member\n(k)   Representative (equivalent to First Class, -Member\nNepal Rastra Bank\n(l)   Two       persons     including   one   woman -Member\nnominated by the Government from amongst\nforeign employment experts\n(m) Two persons consisting of the chairperson of\nthe   foreign       employment    entrepreneurs'\nassociation and one woman representative\n-Member\nnominated by that association\n(n)   Two persons consisting of one woman\nnominated by the Government of Nepal from\namongst the operators of skill-oriented and\norientation trainings on foreign employment\n-Member\n(o)   One person nominated by the Government of\nNepal from amongst the doctors, who have\npassed at least MBBS, of a health institute\n-Member\nrecognized pursuant to Section 72\n(p)   Chairpersons of four recognized trade union\nfederations designated by the Government of\nNepal or four persons consisting of one\n-Member\nnominated by each such federation\n(q)   Representative, Federation of Nepal Chamber -Member\nof Commerce and Industry\n(r)    Representative,     Council   for      Technical -Member\nEducation and Vocational Training\n(s)    Executive Director                                 -Member\nSecretary", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "Tenure of office the members nominated by the Government of\nNepal pursuant to Sub-section (1) shall be of two years.", "children": []}]}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 39", "title": "Functions, duties and powers of the Board", "content": "The functions, duties and powers\nof the Board, in addition to its    functions,     duties   and   powers   set   forth\nelsewhere in this Act, shall be     as follows:-", "children": [{"tier": 3, "nodeType": "clause", "identifier": "(a)", "title": null, "content": "To do, or cause to be done, studies of international labor market and\nexplore, or cause to be explored, new international labor market,", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(b)", "title": null, "content": "To collect, process and publish information for the promotion of foreign\nemployment,", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(c)", "title": null, "content": "To mobilize, or cause to be mobilized, the Foreign Employment Welfare\nFund,", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(d)", "title": null, "content": "To do, or cause to be done, acts required for the protection of interests of\nthe workers who have gone for foreign employment,", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(e)", "title": null, "content": "To formulate, implement, monitor and evaluate programs to utilize the\nskills, capital of, and technology learnt by, the workers who have come\nback from abroad and use the same for the national interests,", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(f)", "title": null, "content": "To do necessary acts in relation to labor agreements to be entered into\nwith various countries,", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(g)", "title": null, "content": "To prescribe qualifications for the registration of institutions providing\nforeign employment orientation trainings,", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(h)", "title": null, "content": "To formulate and approve curricula of foreign employment orientation\ntrainings,", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(i)", "title": null, "content": "To formulate such short-term and long-term policies as required to be\npursued to make the foreign employment business safe, systematic and\ndecent and in relation to the protection of the rights and interests of the\nforeign employment entrepreneurs and submit such policies to the\nGovernment of Nepal,", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(j)", "title": null, "content": "To carry out a comprehensive study on the implementation of the\nForeign Employment Act and give suggestions to the Government of\nNepal,", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(k)", "title": null, "content": "If it appears necessary to review the laws relating to foreign\nemployment, to review the same and give suggestions to the Government\nfor necessary improvements,", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(l)", "title": null, "content": "To give advice to the Government of Nepal in relation to the fixation of\nthe service charges and promotional costs,", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(m)", "title": null, "content": "To give advice to the Government of Nepal to make necessary\narrangements on importing earnings made by Nepalese workers abroad\ninto Nepal in a simple and easy manner,", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(n)", "title": null, "content": "If it is found that any person has done or taken any act or action contrary\nto the laws relating to foreign employment, to write to the concerned\nbody for necessary action,", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(o)", "title": null, "content": "To monitor the institutions licensed to operate the foreign employment\nbusiness,", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(p)", "title": null, "content": "To monitor, or cause to be monitored, the institutions having obtained\nlicense or permission to provide orientation trainings and skill-oriented\ntrainings,", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(q)", "title": null, "content": "If, in carrying out or causing to be carried out monitoring, it is found\nthat any person has done any act in contrary to this Act or the rules\nframed under this Act, to write to the concerned body for necessary\naction,", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(r)", "title": null, "content": "To submit to the Government of Nepal an annual report of the activities\ncarried out by it,", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(s)", "title": null, "content": "To do, or cause to be done, other acts as prescribed.", "children": []}]}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 40", "title": "Meetings and decisions of the Board", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "Meeting of the Board shall be held\nas required.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The meeting of the Board shall be held at such place, time\nand date as may be specified by the chairperson.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The presence of more than fifty percent out of the total number of\nmembers of the Board shall be deemed to constitute a quorum for a meeting of\nthe Board.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "The meeting of the Board shall be presided over by the\nchairperson of the Board, by the vice-chairperson in the absence of the\nchairperson, and by the member selected by the members present at the meeting\nfrom amongst themselves, in the absence of even the vice-chairperson.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "A majority opinion shall prevail at the meeting of the Board. In\nthe event of a tie, the person presiding over the meeting shall exercise the\ncasting vote.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "The decisions of the Board shall be authenticated by the member-\nsecretary.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(7)", "title": null, "content": "The Board may invite any relevant expert or office-bearer as an\nobserver at its meeting.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(8)", "title": null, "content": "Other procedures relating to the meeting of the Board shall be as\ndetermined by the Board itself.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(9)", "title": null, "content": "The chairperson and member of the Board shall, for having\nparticipated in the meeting of the Board, receive such meeting allowance as\nprescribed by the Government of Nepal.", "children": []}]}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 41", "title": "Appointment, functions, duties and powers of Executive Director", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The Government of Nepal shall appoint one Executive Director through\nopen competition, as prescribed, from amongst the persons who have\npossessed the prescribed qualification and are not involved in the foreign\nemployment business, to carry out day-to-day business of the Board, as\nits administrative chief.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "Notwithstanding anything contained in Sub-section (1),\nuntil the office of the Executive Director is filled up, the Government of Nepal\nmay designate any officer employee of at least Gazetted First Class to act as the\nExecutive Director for a maximum period of three months.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The tenure of office of the Executive Director shall be of\nfour years.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "The provisions relating to the remuneration, terms of\nservice and facilities of the Executive Director shall be as prescribed.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "The functions, duties and powers of the Executive Director\nshall be as follows:-\n(a)       To implement, or cause to be implemented, the decisions\nof the Board,\n(b)       To perform such other functions as prescribed.", "children": []}]}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 42", "title": "Secretariat of the Board", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The Board shall have a separate secretariat of its\nown.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The Executive Director shall be the chief of the secretariat.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The Government of Nepal shall provide necessary employees for\nthe secretariat of the Board.", "children": []}]}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-9", "title": null, "content": "Offense and Punishment", "children": [{"tier": 2, "nodeType": "rule", "identifier": "Rule 43", "title": "Punishment to be imposed in the event of carrying on foreign employment business without license", "content": "If any person carries on the foreign employment\nbusiness in contrary to Section 10 or collects any amount with intent to engage\na person in foreign employment or sends a person abroad by giving false\nassurance or lures a person to be engaged in foreign employment, the amount\nso received and an amount to be set by fifty percent of that amount shall be\nrecovered from that person as compensation and the expenses incurred by that\nother person in going to and coming from abroad shall also be realized and that\nperson shall be punished with a fine of three hundred thousand rupees to five\nhundred thousand rupees and with imprisonment for a term of three years to\nseven years. In the event that such person has not yet sent that person abroad,\nhalf the punishment shall be imposed.", "children": []}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 44", "title": "Punishment to be imposed in the event of sending workers by licensee without obtaining permission", "content": "If any licensee sends any worker abroad\nwithout obtaining permission from the Department or collects any amount by\ngiving false assurance or showing enticement that the licensee would engage\nany person in foreign employment but does not send that person abroad, the\namount so collected and an amount to be set by fifty percent of that amount\nshall be recovered from that licensee, and such licensee shall be punished with\na fine of three hundred thousand rupees to five hundred thousand rupees and\nwith imprisonment for a term of three years to seven years; and the license of\nsuch licensee shall also be revoked.", "children": []}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 45", "title": "Punishment to be imposed in the event of sending minors for foreign employment", "content": "If any licensee sends any minor for foreign employment in\ncontravention of Section 7, the licensee shall be punished with a fine of three\nhundred thousand rupees to five hundred thousand rupees and with\nimprisonment for a term of three years to seven years.", "children": []}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 46", "title": "Punishment to be imposed in the event of sending workers to countries not opened by Government", "content": "If any licensee sends any worker to any country\nwhich has not been opened by the Government of Nepal for foreign\nemployment or obtains a visa from any country which has been opened but\nsends any worker to a country which has not been opened, the licensee so\nsending a worker shall be punished with a fine of three hundred thousand\nrupees to seven hundred thousand rupees and with imprisonment for a term of\nthree years to five years. In case the licensee has collected any amount for\nsending the worker but has not yet sent the worker, the licensee shall be subject\nto half the punishment.", "children": []}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 47", "title": "Punishment to be imposed in the event of concealing or altering document or report", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "If any licensee knowingly conceals any document or report\nrequired to be maintained under this Act or the Rules framed under this Act or\nalters any matter therein or makes any false contents or causes any one to\nprepare false details, such licensee shall be punished with a fine of one hundred\nthousand rupees to three hundred thousand rupees and with imprisonment for a\nterm of six months to one year.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "If any licensee who has been punished pursuant to Sub-section (1)\nis held to have repeated the offense, such licensee shall be subject to two-fold\npunishment, and the license obtained by such licensee shall be revoked.", "children": []}]}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 48", "title": "Punishment to be imposed in the event of opening branch office without permission", "content": "If any licensee opens a branch office without obtaining permission\nof the Department, the Department may issue an order to punish the licensee\nwith a fine at the rate of two hundred thousand rupees for each branch and\nclose that office.", "children": []}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 49", "title": "Punishment to be imposed in the event of failure to publish advertisement", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "If any licensee fails to publish an advertisement pursuant to Section 16\nor publishes an advertisement without obtaining permission of the Department,\nthe Department shall punish such licensee with a fine of fifty thousand rupees\nand cancel    such an advertisement.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "If any licensee fails to set out such details in an advertisement as\nrequired to be set out as per the permission received pursuant to Section 15, the\nDepartment shall cause that licensee to correct and republish the advertisement.", "children": []}]}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 50", "title": "Punishment to be imposed in the event of failure to publish selection list", "content": "If any licensee fails to publish a selection list of workers pursuant to Section 17\nor publishes it but fails to give information thereof to the Department, the\nDepartment may punish such licensee with a fine of fifty thousand rupees and\norder to republish the selection list.", "children": []}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 51", "title": "Punishment to be imposed in the event of refusal to return amount or provide compensation", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "If any licensee fails to return the amount set forth in\nSub-section (2) of Section 20 within the time set forth in that sub- section    or\nrefuses to provide compensation referred to in Sub-section (2) of Section      36,\nthe Department may get such amount or compensation returned or provided to\nthe concerned worker from the cash deposit made by that licensee pursuant to\nSection 11, punish such licensee with a fine of one hundred thousand rupees and\nrevoke the license.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "If the amount or compensation is to be returned or provided\npursuant to Sub-section (1) and the cash deposit made by the licensee pursuant\nto Section 11 is not sufficient to cover such amount or compensation, the\nDepartment shall give a time-limit of sixty days to the licensee to pay the\nshortfall amount and if the licensee fails to pay the amount within that time-\nlimit, the amount shall be realized from the assets of the licensee.", "children": []}]}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 52", "title": "Punishment to be imposed in the event of sending workesr by licensee on personal basis", "content": "If any licensee sends any worker on personal basis in\ncontravention of Sub-section (3) of Section 21, such licensee shall be punished\nwith a fine of one hundred thousand rupees to three hundred thousand rupees or\nwith revocations of license or with both punishments.", "children": []}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 53", "title": "Punishment to be imposed in the event of collecting visa fees, service charges and promotional costs in excess", "content": "If any licensee collects visa fees\nwhere free visa has been received or collects fees or costs in excess of the fees\nor costs as prescribed, the Department shall require the licensee to return such\nfees not to be charged or such excess fees or costs to the concerned person and\npunish such licensee with a fine of one hundred thousand rupees.", "children": []}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 54", "title": "Punishment to be imposed in the event of failure to observe order or direction", "content": "Except as otherwise provided for in this Chapter, the Department\nmay warn for the first instance any licensee who fails to observe this Act and\nthe rules, orders or directions framed or issued under this Act, punish such\nlicensee with a fine of fifty thousand rupees for the second instance and with a\nfine of one hundred thousand rupees, along with revocation of license, for the\nthird instance of the same offense.", "children": []}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 55", "title": "Punishment to be imposed in the event of doing or causing to be done act contrary to contract", "content": "If any licensee, after making a contract with any worker\nfor work in a company, engages the worker in work for remuneration or\nfacilities lower that or in another company for a work of such nature as is\ndifferent than that specified in the contract or does not engage the worker in the\nwork for which the worker has been sent for foreign employment but engages\nthe worker in another work or engages the worker in work for remuneration and\nfacilities less than the remuneration and facilities offered previously, the\nDepartment shall punish such licensee with a fine of one hundred thousand\nrupees and require the licensee to pay the shortfall amount of such\nremuneration and facilities.", "children": []}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 56", "title": "Punishment to be imposed on accomplice", "content": "A person who is an accomplish\nin any offense referred to in this Act or aids and abets the commission of such\noffense shall be subject to half the punishment to be imposed in the case of that\noffense.", "children": []}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 57", "title": "Punishment to person who acts as chief", "content": "If any firm, company, institution or\nlicensee commits any offense punishable under this Chapter and the office-\nbearer or employee who has committed such offense is identified, then such\noffice-bearer or employee shall, and if such office-bearer or employee cannot\nbe identified, the person who has acted as the chief of such firm, company or\ninstitution at the time of commission of the offense shall, be subject to\npunishment.", "children": []}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 58", "title": "No license be re-issued", "content": "After the license of any licensee has been revoked\npursuant to this Chapter, no license shall be re-issued to the same institution\nand operator.", "children": []}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 59", "title": "Opportunity for defense", "content": "Prior to revoking the license pursuant to this\nChapter, the concerned licensee shall be provided with an opportunity for\ndefense.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-10", "title": null, "content": "Investigation and Inquiry", "children": [{"tier": 2, "nodeType": "rule", "identifier": "Rule 60", "title": "Limitation for complaint", "content": "Except in cases of the offenses punishable under\nSections 43, 44, 45, 46 and 47, no complaint shall be entertained if it is not\nmade within one year from the date of commission of any other offense\npunishable under this Act.\nProvided that this Section shall not be deemed to bar the making of a complaint\nby a worker, who has gone for foreign employment, within one year after the\ndate of his or her arrival in Nepal.", "children": []}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 61", "title": "Investigation and inquiry of offense relating to foreign employment", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "If\nthe Department receives information directly or indirectly upon a complaint\nmade by any person or in any other manner that any offense has been or is\ngoing to be committed in contravention of this Act or the rules framed under\nthis Act, the Department may designate any officer of at least Gazetted Third\nClass as the investigation officer for the investigation of and inquiry into such\noffense.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "In making investigation of and inquiry into any offense pursuant\nto Sub-section (1), the investigation officer shall have the same powers as the\npolice have under the prevailing laws, which include powers to arrest the\nperson involved in the offense, search any place in relation to the offense, take\ncustody of documents or other things related with the offense, record\ndepositions and execute recognizance deeds.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "In making investigation of and inquiry into any offense pursuant\nto Sub-section (2), the investigation officer may get the accused to make\ndeposition, and in the event that the immediately available evidences constitute\nsufficient grounds to show the accused as offender, get the accused to appear\non the appointed dates, assigning the reasons for the same, release the accused\non bail or guarantee or detain the accused ,with the permission of the case\ntrying authority, if the accused fails to furnish such bail or guarantee or detain\nthe accused, with the permission of the case trying authority, for a maximum\nperiod of thirty days, not exceeding seven days at a time.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "In filing a case in his or her name after making investigation of\nand inquiry into pursuant to this Section, the investigation officer shall get\nadvice of the government attorney.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "It shall be the duty of all the concerned including the police to\nprovide necessary assistance to the investigation officer in the investigation and\ninquiry under this Section.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "The investigation officer investigating of and inquiring into an\noffense relating to foreign employment pursuant to this Section may, if there\nare appropriate and adequate reasons in the course of investigation, submit a\nreport, accompanied by the appropriate and adequate reasons, to the\nDepartment for the suspension of the license of any licensee.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(7)", "title": null, "content": "The Department may, based on the report referred to in Sub-\nsection (6), suspend the license of such licensee for a maximum period of six\nmonths.", "children": []}]}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 62", "title": "Power to arrest", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "Where any person has committed an offense referred to in\nSection 43 of this Act, the police employee may, if he or she considers that the\nperson could abscond if that person is not arrested immediately, may arrest\nsuch person without warrant.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The person arrested pursuant to Sub-section (1) shall be produced\nbefore the case trying authority within twenty four hours excluding the time\nrequired for journey.", "children": []}]}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-11", "title": null, "content": "Trial and Settlement of Cases", "children": [{"tier": 2, "nodeType": "rule", "identifier": "Rule 63", "title": "To be state cases", "content": "The cases under this Act shall be sate cases.", "children": []}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 64", "title": "Provisions relating to Foreign Employment Tribunal", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "For              originally\ntrying and settling cases other than those punishable by the Department as\nmentioned in this Act, the Government of Nepal shall, by a notification in the\nNepal Gazette, constitute a three-member Foreign Employment Tribunal, under\nthe chairpersonship of the Judge of Appellate Court, comprising the case trying\nauthority of the Labor Court and the First Class Officer of Judicial Service\nrecommended by the Judicial Service Commission.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The tenure of the chairperson and members of the Foreign\nEmployment Tribunal shall be of four years.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The terms and conditions of service and facilities of the chairperson\nand members of the Foreign Employment Tribunal shall be as prescribed.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "The Foreign Employment Tribunal shall exercise its jurisdiction as\nprescribed.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "Pending the constitution of the Tribunal as referred to in this Section,\nthe acts and action to be done and taken by the Foreign Employment Tribunal\npursuant to this Act shall be done and taken by the concerned District Court.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "The Government of Nepal shall provide such employees as may be\nrequired for the Foreign Employment Tribunal.", "children": []}]}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 65", "title": "Procedures of cases", "content": "The cases to be filed under this Act shall be tried and\nsettled in accordance with the Summary Procedures Act, 2028 (1971).", "children": []}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 66", "title": "Appeal", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "A party who is not satisfied with a decision made by the\nDepartment pursuant to this Act may make an appeal to the Government of\nNepal within thirty-five days from the date of such decision.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "A party who is not satisfied with a decision made by the Foreign\nEmployment Tribunal pursuant to this Act may make an appeal to the Supreme\nCourt within thirty-five days from the date of such decision.", "children": []}]}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-12", "title": null, "content": "Miscellaneous", "children": [{"tier": 2, "nodeType": "rule", "identifier": "Rule 67", "title": "Foreign Employment Department", "content": "There shall be a Foreign Employment Department under the Ministry of Labor\nand Transport Management to carry out functions relating to foreign\nemployment.", "children": []}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 68", "title": "Appointment of Labor Attache", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The Government of Nepal shall appoint\nat least Gazetted    officer as the Labor Attaché for a country where five\nthousand or more workers have been sent for foreign employment.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The functions, duties and powers of the Labor Attaché shall be as\nfollows:-\n(a)     To give information to the Government of Nepal about the\ncondition of labor and employment, factual information about\nimmigration of the country where Nepalese workers are working\nand steps taken by that country for the protection of labor and\ninternational human rights and interests of workers,\n(b)     If there arises any dispute between a worker, employer institution\nor licensee, to assist in the resolution of such dispute,\n(c)     To make necessary arrangements for bringing back to Nepal any\nworker who has been helpless in the course of foreign\nemployment,\n(d)      If any work corresponding to the skills of the Nepalese worker is\navailable in the concerned country, to provide information thereon\nto the Government of Nepal,\n(e)     To take initiation in sending back the dead body of any worker,\nwho has been a victim of natural calamity or who has died due to\nany cause, to Nepal with the assistance of the concerned country\nor employer institution,\n(f)     To make efforts to make a bilateral agreement at the governmental\nlevel for the supply of workers from Nepal,\n(g)     To provide necessary consultancy to workers, and discourage\nthem to do any work other than that set forth in the agreement,\n(h)     To supervise any activity that may affect the workers, and\n(i)     To perform such other functions as prescribed by the Government\nof Nepal from time to time.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "If both diplomatic mission and Labor Attaché are in any foreign country,\nthe Labor Attaché shall have the obligation to perform the functions and\nduties set forth in Sub-section (1).", "children": []}]}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 69", "title": "Repatriation of income of workers", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "Saving amounts earned by the\nNepalese workers who have gone for foreign employment shall be repatriated\nto Nepal through a bank or an institution licensed to provide banking service.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "Notwithstanding anything contained in Sub-section (1), any\nworker may carry with him or her the saving amount earned by him or her in\nthe course of foreign employment when he or she comes back to Nepal.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "If any Nepalese worker repatriates the earning, earned by him or\nher abroad within the period set forth in the agreement, to Nepal through a bank\nor an institution licensed to provide banking service, the facility as prescribed\nshall be provided to such worker.", "children": []}]}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 70", "title": "Prohibition on issuance of license", "content": "Notwithstanding anything contained\nelsewhere in this Act, if a person who has been punished by the court for any\noffense under this Act is a manager or director of any company and a period of\nfive years has not elapsed after the service of such punishment, license shall not\nbe issued to such institution.", "children": []}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 71", "title": "Power of Government of Nepal to reward", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "On recommendation of the\nBoard, the Government of Nepal may, each year, make reward, along with a\nletter of appreciation, to one excellent licensee, on the basis of prescribed\ncriteria.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "Other provisions on making reward to the licensee shall be as\nprescribed.", "children": []}]}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 72", "title": "Provisions relating to health check up", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "A worker who goes for foreign\nemployment shall, prior to going abroad, get his or her health checked up by a\nhealth institution having obtained permission from the Government of Nepal.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "If a person who has gone for foreign employment after having\nundergone health check up pursuant to Sub-section (1) is compelled to return to\nNepal because of a false health check up report given knowingly or recklessly\nor maliciously, the institution which has given such false health check up report\nshall bear the expenses incurred in going for foreign employment and returning\nto Nepal.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "There shall be an expert committee as prescribed to make decision\nwhether a false health check up report has been given or not pursuant to Sub-\nsection (2).", "children": []}]}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 73", "title": "Provision of Labor Desk", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The Government of Nepal shall establish a\nLabor Desk at the international airport and other place, as required, in order to\nexamine whether workers proceeding for foreign employment are going for\nsuch employment in accordance with this Act or not.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The Labor Desk referred to in Sub-section (1) shall examine\nwhether the workers have the labor permit, orientation certificate, receipt or\nvoucher of payment of money as well as necessary documents.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The Labor Desk referred to in Sub-section (1) shall send a report,\naccompanied by the records of workers who have gone for foreign\nemployment, to the Ministry each week.", "children": []}]}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 74", "title": "Provisions relating to opening of branch and appointment of agent", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "A\nlicensee may open its branch or appoint its agent in a country where it has sent\nworkers by obtaining permission, as prescribed, from the Department.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "A licensee may open its branch or appoint its agent within Nepal\nby obtaining permission, as prescribed, from the Department.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "In appointing an agent pursuant to Sub-section (1) or (2), deposit\nas prescribed shall be furnished and the licensee itself shall be responsible for\nany acts and actions done and taken by such an agent.", "children": []}]}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 75", "title": "Provisions on sending workers back to Nepal", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "Where any worker becomes\nhelpless by the reason that the worker has not got such facilities as set forth in\nthe contract and such worker has to return to Nepal, the concerned licensee\nshall arrange for the returning of such worker to Nepal.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "Where Nepalese workers have to be immediately brought back to\nNepal due to a war, epidemic, natural calamity in the country where such\nworkers are engaged in employment, the Government of Nepal shall make\narrangements for repatriating such workers through the diplomatic mission or\nLabor Attaché.", "children": []}]}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 76", "title": "Returning to Nepal after expiry of term of visa", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "A worker who has gone\nfor foreign employment pursuant to this Act shall return to Nepal after the\nexpiry of the term of visa issued by the concerned country.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "It shall be the obligation of the licensee to get a worker,\nwho does not return to Nepal pursuant to Sub-section (1), to return to Nepal,\nwith the assistance of the Department.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "The Government of Nepal may restrict the worker who has\nbeen so got returned to go abroad for three years after the worker has been got\nreturned to Nepal pursuant to Sub-section (2).", "children": []}]}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 77", "title": "Provision of facilities to licensee", "content": "The facilities, as prescribed, shall be\nprovided to the licensee while doing transaction of foreign currency in the\ncourse of carrying on the foreign employment business.", "children": []}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 78", "title": "To make public details relating to licensee", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The Department shall, from\ntime to time, make public through various newspapers or its website details\nincluding the name, address, telephone number of the institution which has\nobtained license pursuant to this Act, details of agent or branch, if any, it has\nappointed or opened and the term of its license.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "Where any licensee is being subject to investigation for an offense\nreferred to in this Act or the license of any licensee has been revoked, such\ndetails shall also be updated while making public the details pursuant to Sub-\nsection (1).", "children": []}]}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 79", "title": "Provisions relating to activities of Department", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The        Department     shall\nsubmit a monthly report of the activities which it has carried out pursuant to\nthis Act to the Ministry of Labor and Transport Management, Government of\nNepal.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The Ministry may, from time to time, give necessary direction to the\nDepartment in relation to the activities to be carried out pursuant to this Act.", "children": []}]}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 80", "title": "Record and report", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "A licensee shall maintain, as prescribed, the records\nof workers sent for foreign employment. The Department may, at any time,\ninspect, procure and examine such records.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "Each licensee shall submit an annual report setting out the prescribed\ndetails to the Department within thirty days after the expiry of each financial\nyear.", "children": []}]}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 81", "title": "Delegation of powers", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The Government of Nepal may, by a notification in\nthe Nepal Gazette, delegate any powers conferred to it under this Act to any\ngovernmental body or authority.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "The Board may delegate any powers conferred to it under this Act to\nthe Executive Director.", "children": []}]}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 82", "title": "Power to remove difficulties", "content": "If there    arises any difficulty with          the\nimplementation of the objectives of this Act, the Government of Nepal may, by\na notification in the Nepal Gazette, issue necessary orders for the removal of\nsuch difficulty.", "children": []}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 83", "title": "Saving of acts done in good faith", "content": "No governmental employee shall be\npersonally liable in relation to any act done in good faith in exercise of the\npowers conferred by this Act.", "children": []}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 84", "title": "Prevalence of Act", "content": "The matters contained in this Act shall be governed by this\nAct, and the other matters shall be governed by the prevailing Nepal laws.", "children": []}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 85", "title": "Powers to frame Rules", "content": "The Government of Nepal may frame necessary Rules\nfor the attainment of the objectives of this Act.", "children": []}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 86", "title": "Repeal and saving", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "The Foreign Employment Act, 2042 (1985) is hereby\nrepealed.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "All acts done and actions taken pursuant to the Foreign\nEmployment Act, 2042 (1985) shall be deemed to have been done and taken\nunder this Act.", "children": []}]}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 87", "title": "Transfer of cases", "content": "The cases which have been investigated and inquired by the\nDepartment under the Foreign Employment Act, 2042 (1985) and filed with the\nDistrict Court at the time of commencement of this Act shall be transferred to\nthe Tribunal referred to in Section 64 after the constitution of that Tribunal.", "children": []}]}]$CODEx0c941c7c1aa3$::jsonb) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,"originalTitle"=EXCLUDED."originalTitle","documentType"=EXCLUDED."documentType","yearBs"=EXCLUDED."yearBs","yearAd"=EXCLUDED."yearAd","totalPages"=EXCLUDED."totalPages",nodes=EXCLUDED.nodes;
